_TABLES = {"en": _EN, "de": _DE, "fr": _FR, "ja": _JA}


def form_labels(language: str) -> dict[str, str]:
    """Labels for `language`, falling back to English for an unknown code."""
    table = _TABLES.get(language, _EN)
    # Fall back key-by-key so a partially translated table never renders an empty label.
    merged = dict(_EN)
    merged.update(table)
    return merged


def supported_languages() -> tuple[str, ...]:
    return tuple(_TABLES.keys())
